import os, pty, select, sys, termios, fcntl, struct, time
pid, fd = pty.fork()
if pid == 0:
    os.chdir('/tmp/walkprobe.jdBP4I')
    os.execv('/workspace/executable', ['/workspace/executable'])

# set size 80x24
fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', 24, 80, 0, 0))

def read_for(sec):
    end = time.time() + sec
    chunks = []
    while time.time() < end:
        r, _, _ = select.select([fd], [], [], 0.05)
        if fd in r:
            try:
                data = os.read(fd, 4096)
            except OSError:
                break
            if not data:
                break
            chunks.append(data)
    return b''.join(chunks)

out1 = read_for(0.5)
os.write(fd, b'\x1b]11;rgb:0000/0000/0000\x07\x1b[1;1R')
out2 = read_for(0.5)
