out3 = read_for(0.5)
os.write(fd, b'q')
out4 = read_for(0.5)
for name, data in [('startup1', out1), ('startup2', out2), ('after_j', out3), ('after_q', out4)]:
    print('---', name, len(data))
    print(data)
