package main

import (
	"encoding/base64"
	"os"
	"syscall"
	"unsafe"
)

type tty struct {
	file     *os.File
	orig     syscall.Termios
	raw      bool
	lastCols int
	lastRows int
}

type keyKind int

const (
	keyRune keyKind = iota
	keyEnter
	keyBackspace
	keyEsc
	keyCtrlC
	keyUp
	keyDown
	keyDelete
	keyJumpFirst
	keyJumpLast
)

type keyEvent struct {
	kind keyKind
	r    rune
}

func openTTY() (*tty, error) {
	f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return nil, err
	}
	return &tty{file: f}, nil
}

func (t *tty) close() error {
	return t.file.Close()
}

func (t *tty) enterRaw() error {
	fd := int(t.file.Fd())
	orig, err := tcgetattr(fd)
	if err != nil {
		return err
	}
	t.orig = orig
	raw := orig
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Cc[syscall.VMIN] = 0
	raw.Cc[syscall.VTIME] = 1
	if err := tcsetattr(fd, raw); err != nil {
		return err
	}
	t.raw = true
	_, _ = t.file.WriteString("\x1b[?25l\x1b[?2004h")
	return nil
}

func (t *tty) exitRaw() error {
	if !t.raw {
		return nil
	}
	_, _ = t.file.WriteString("\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l")
	err := tcsetattr(int(t.file.Fd()), t.orig)
	t.raw = false
	return err
}

func (t *tty) suspend() error {
	if !t.raw {
		return nil
	}
	return t.exitRaw()
}

func (t *tty) resume() error {
	if t.raw {
		return nil
	}
	return t.enterRaw()
}

func (t *tty) size() (int, int) {
	ws, err := getWinSize(int(t.file.Fd()))
	if err != nil || ws.Col == 0 || ws.Row == 0 {
		if t.lastCols == 0 {
			return 80, 24
		}
		return t.lastCols, t.lastRows
	}
	t.lastCols = int(ws.Col)
	t.lastRows = int(ws.Row)
	return t.lastCols, t.lastRows
}

func (t *tty) readEvent() (keyEvent, bool, error) {
	var buf [16]byte
	n, err := t.file.Read(buf[:1])
	if err != nil {
		return keyEvent{}, false, err
	}
	if n == 0 {
		return keyEvent{}, false, nil
	}
	b := buf[0]
	switch b {
	case 0x03:
		return keyEvent{kind: keyCtrlC}, true, nil
	case '\r', '\n':
		return keyEvent{kind: keyEnter}, true, nil
	case 0x7f, 0x08:
		return keyEvent{kind: keyBackspace}, true, nil
	case 0x1b:
		seq := []byte{0x1b}
		for {
			n, err := t.file.Read(buf[:])
			if err != nil {
				return keyEvent{}, false, err
			}
			if n == 0 {
				break
			}
			seq = append(seq, buf[:n]...)
			if isCSIComplete(seq) {
				break
			}
		}
		return parseEscape(seq), true, nil
	default:
		return keyEvent{kind: keyRune, r: rune(b)}, true, nil
	}
}

func parseEscape(seq []byte) keyEvent {
	s := string(seq)
	switch s {
	case "\x1b":
		return keyEvent{kind: keyEsc}
	case "\x1b[A":
		return keyEvent{kind: keyUp}
	case "\x1b[B":
		return keyEvent{kind: keyDown}
	case "\x1b[3~":
		return keyEvent{kind: keyDelete}
	case "\x1b[1;2A", "\x1b[1;2D":
		return keyEvent{kind: keyJumpFirst}
	case "\x1b[1;2B", "\x1b[1;2C":
		return keyEvent{kind: keyJumpLast}
	default:
		return keyEvent{kind: keyEsc}
	}
}

func isCSIComplete(seq []byte) bool {
	if len(seq) < 2 || seq[0] != 0x1b {
		return true
	}
	last := seq[len(seq)-1]
	return (last >= 'A' && last <= 'Z') || last == '~'
}

func (t *tty) copyOSC52(text string) {
	encoded := base64.StdEncoding.EncodeToString([]byte(text))
	_, _ = t.file.WriteString("\x1b]52;c;" + encoded + "\a")
}

func tcgetattr(fd int) (syscall.Termios, error) {
	var term syscall.Termios
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&term)), 0, 0, 0)
	if errno != 0 {
		return term, errno
	}
	return term, nil
}

func tcsetattr(fd int, term syscall.Termios) error {
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&term)), 0, 0, 0)
	if errno != 0 {
		return errno
	}
	return nil
}

type winSize struct {
	Row    uint16
	Col    uint16
	XPixel uint16
	YPixel uint16
}

func getWinSize(fd int) (winSize, error) {
	var ws winSize
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)), 0, 0, 0)
	if errno != 0 {
		return ws, errno
	}
	return ws, nil
}

