func (e identExpr) eval(ctx statusContext) (any, error) {
	switch e.name {
	case "current_file":
		return ctx.current, nil
	case "files":
		out := make([]any, 0, len(ctx.files))
		for _, file := range ctx.files {
			out = append(out, file)
		}
		return out, nil
	default:
		return nil, fmt.Errorf("unknown identifier %q", e.name)
	}
}

type arrayExpr struct{ items []statusExpr }

func (e arrayExpr) eval(ctx statusContext) (any, error) {
	out := make([]any, 0, len(e.items))
	for _, item := range e.items {
		value, err := item.eval(ctx)
		if err != nil {
			return nil, err
		}
		out = append(out, value)
	}
	return out, nil
}

type callExpr struct {
	receiver statusExpr
	name     string
	args     []statusExpr
}

func (e callExpr) eval(ctx statusContext) (any, error) {
	var recv any
	var err error
	if e.receiver != nil {
		recv, err = e.receiver.eval(ctx)
		if err != nil {
			return nil, err
		}
	}
	args := make([]any, 0, len(e.args))
	for _, arg := range e.args {
		value, err := arg.eval(ctx)
		if err != nil {
			return nil, err
		}
		args = append(args, value)
	}
	return callStatusFunc(e.name, recv, args, ctx)
}

type pipeExpr struct {
	left statusExpr
	call callExpr
}

func (e pipeExpr) eval(ctx statusContext) (any, error) {
	value, err := e.left.eval(ctx)
	if err != nil {
		return nil, err
	}
	args := make([]statusExpr, 0, len(e.call.args)+1)
	args = append(args, literalExpr{value: value})
	args = append(args, e.call.args...)
	return callExpr{name: e.call.name, receiver: e.call.receiver, args: args}.eval(ctx)
}

func parseStatusProgramFromEnv() (*statusProgram, error) {
	source := strings.TrimSpace(os.Getenv("WALK_STATUS_BAR"))
	if source == "" {
		return nil, nil
	}
	parser := statusParser{src: source}
	root, err := parser.parse()
	if err != nil {
		return nil, err
	}
	return &statusProgram{root: root}, nil
}

func (p *statusProgram) eval(ctx statusContext) (any, error) {
	return p.root.eval(ctx)
}

type statusParser struct {
	src string
	pos int
}

func (p *statusParser) parse() (statusExpr, error) {
	expr, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	p.skipSpace()
	if p.pos != len(p.src) {
		return nil, fmt.Errorf("unexpected token %q", p.src[p.pos:])
	}
	return expr, nil
}

func (p *statusParser) parsePipe() (statusExpr, error) {
	left, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	for {
		p.skipSpace()
		if !p.consume('|') {
			return left, nil
		}
		p.skipSpace()
		call, err := p.parseCall(nil)
		if err != nil {
			return nil, err
		}
		left = pipeExpr{left: left, call: call}
	}
}

func (p *statusParser) parsePrimary() (statusExpr, error) {
	p.skipSpace()
	if p.pos >= len(p.src) {
		return nil, fmt.Errorf("unexpected token EOF")
	}
	switch p.src[p.pos] {
	case '"':
		return p.parseString()
	case '[':
		return p.parseArray()
	case '(':
		p.pos++
		expr, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		if !p.consume(')') {
			return nil, fmt.Errorf("unexpected token EOF")
		}
		return expr, nil
	default:
		if isDigit(p.src[p.pos]) {
			return p.parseNumber()
		}
		name, err := p.parseIdent()
		if err != nil {
			return nil, err
		}
		expr := statusExpr(identExpr{name: name})
		for {
			p.skipSpace()
			if p.consume('.') {
				method, err := p.parseIdent()
				if err != nil {
					return nil, err
				}
				call, err := p.parseCall(expr, method)
				if err != nil {
					return nil, err
				}
				expr = call
				continue
			}
			if p.peek() == '(' {
				call, err := p.parseCall(nil, name)
				if err != nil {
					return nil, err
				}
				expr = call
			}
			return expr, nil
		}
	}
}

func (p *statusParser) parseCall(receiver statusExpr, preset ...string) (callExpr, error) {
	name := ""
	if len(preset) != 0 {
		name = preset[0]
	} else {
		ident, err := p.parseIdent()
		if err != nil {
			return callExpr{}, err
		}
		name = ident
	}
	if !p.consume('(') {
		return callExpr{}, fmt.Errorf("unexpected token EOF")
	}
	var args []statusExpr
	p.skipSpace()
	if p.consume(')') {
		return callExpr{receiver: receiver, name: name, args: args}, nil
	}
	for {
		arg, err := p.parsePipe()
		if err != nil {
			return callExpr{}, err
		}
		args = append(args, arg)
		p.skipSpace()
		if p.consume(')') {
			break
		}
		if !p.consume(',') {
			return callExpr{}, fmt.Errorf("unexpected token EOF")
		}
	}
	return callExpr{receiver: receiver, name: name, args: args}, nil
}

func (p *statusParser) parseString() (statusExpr, error) {
	p.pos++
	start := p.pos
	for p.pos < len(p.src) && p.src[p.pos] != '"' {
		if p.src[p.pos] == '\\' && p.pos+1 < len(p.src) {
			p.pos += 2
			continue
		}
		p.pos++
	}
	if p.pos >= len(p.src) {
		return nil, fmt.Errorf("unexpected token EOF")
	}
	raw := p.src[start:p.pos]
	p.pos++
	raw = strings.ReplaceAll(raw, `\"`, `"`)
	return literalExpr{value: raw}, nil
}

func (p *statusParser) parseNumber() (statusExpr, error) {
	start := p.pos
	for p.pos < len(p.src) && isDigit(p.src[p.pos]) {
		p.pos++
	}
	n, err := strconv.Atoi(p.src[start:p.pos])
	if err != nil {
		return nil, err
	}
	return literalExpr{value: n}, nil
}

func (p *statusParser) parseArray() (statusExpr, error) {
	p.pos++
	var items []statusExpr
	for {
		p.skipSpace()
		if p.consume(']') {
			return arrayExpr{items: items}, nil
		}
		item, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		items = append(items, item)
		p.skipSpace()
		if p.consume(']') {
			return arrayExpr{items: items}, nil
		}
		if !p.consume(',') {
			return nil, fmt.Errorf("unexpected token EOF")
		}
	}
}

func (p *statusParser) parseIdent() (string, error) {
	p.skipSpace()
	start := p.pos
	for p.pos < len(p.src) {
		r := p.src[p.pos]
		if r == '_' || r == '-' || isAlpha(r) || isDigit(r) {
			p.pos++
			continue
		}
		break
	}
	if start == p.pos {
		return "", fmt.Errorf("unexpected token EOF")
	}
	return p.src[start:p.pos], nil
}

func (p *statusParser) skipSpace() {
	for p.pos < len(p.src) && (p.src[p.pos] == ' ' || p.src[p.pos] == '\t' || p.src[p.pos] == '\n') {
		p.pos++
	}
}

func (p *statusParser) consume(ch byte) bool {
	p.skipSpace()
	if p.pos < len(p.src) && p.src[p.pos] == ch {
		p.pos++
		return true
	}
	return false
}

func (p *statusParser) peek() byte {
	p.skipSpace()
	if p.pos >= len(p.src) {
		return 0
	}
	return p.src[p.pos]
}

func isDigit(b byte) bool { return b >= '0' && b <= '9' }
func isAlpha(b byte) bool { return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z') }

func callStatusFunc(name string, receiver any, args []any, ctx statusContext) (any, error) {
	switch name {
	case "Sprintf":
		if len(args) == 0 {
			return "", nil
		}
		format := fmt.Sprint(args[0])
		return fmt.Sprintf(format, args[1:]...), nil
	case "PadLeft":
		if len(args) < 2 {
			return "", nil
		}
		return padLeft(fmt.Sprint(args[0]), asInt(args[1])), nil
	case "PadRight":
		if len(args) < 2 {
			return "", nil
		}
		return padRight(fmt.Sprint(args[0]), asInt(args[1])), nil
	case "Size":
		info := entryInfo(receiver, ctx.current)
		return formatSize(info), nil
	case "Mode":
		info := entryInfo(receiver, ctx.current)
		return formatMode(info), nil
	case "ModTime":
		info := entryInfo(receiver, ctx.current)
		return formatModTime(info), nil
	case "Owner":
		info := entryInfo(receiver, ctx.current)
		return formatOwner(info), nil
	case "join":
		if len(args) < 2 {
			return "", nil
		}
		items, _ := args[0].([]any)
		parts := make([]string, 0, len(items))
		for _, item := range items {
			parts = append(parts, fmt.Sprint(item))
		}
		return strings.Join(parts, fmt.Sprint(args[1])), nil
	case "Name":
		switch value := receiver.(type) {
		case entry:
			return value.Name, nil
		default:
			return "", nil
		}
	default:
		return nil, fmt.Errorf("unknown function %q", name)
	}
}

func entryInfo(receiver any, fallback entry) fs.FileInfo {
	switch value := receiver.(type) {
	case entry:
		return value.LInfo
	default:
		return fallback.LInfo
	}
}

func asInt(v any) int {
	switch value := v.(type) {
	case int:
		return value
	case int64:
		return int(value)
	case float64:
		return int(value)
	default:
		n, _ := strconv.Atoi(fmt.Sprint(v))
		return n
	}
}

